pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount) public {
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        // Ensure overflow occurs: putAmount + putAmount > type(uint256).max
        vm.assume(putAmount > type(uint256).max / 2);
        vm.assume(putAmount <= type(uint256).max - putAmount);
        vm.assume(collectAmount <= putAmount);

        address user = address(0x1234);
        vm.deal(user, putAmount * 2);

        c.Initialized();
        c.SetMinSum(0);

        vm.prank(user);
        c.Put{value: putAmount}(0);

        vm.prank(user);
        // second Put to trigger overflow
        c.Put{value: putAmount}(0);

        (uint unlock, uint balance) = c.Acc(user);
        assertTrue(balance == putAmount + putAmount);
    }
}

