pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant ALICE = address(0x1);
    address constant BOB = address(0x2);
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Bound amounts to avoid reverts unrelated to the overflow bug
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(depositAmount < type(uint128).max);
        vm.assume(collectAmount < type(uint128).max);

        // Setup: initialize and set MinSum to 0 so Collect is not blocked by MinSum
        c.SetMinSum(0);
        c.Initialized();

        // ALICE deposits
        vm.deal(ALICE, depositAmount);
        vm.prank(ALICE);
        c.Put{value: depositAmount}(0);

        // BOB deposits same amount. In the buggy version, overflow can happen if depositAmount*2 > uint256.max
        // but we bound to uint128.max so no overflow on the correct contract, but the buggy one lacks overflow check.
        vm.deal(BOB, depositAmount);
        vm.prank(BOB);
        c.Put{value: depositAmount}(0);

        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + 1);

        // BOB tries to collect more than his recorded balance but within total contract balance
        // In correct contract: Acc[BOB].balance = depositAmount, so collectAmount <= depositAmount required.
        // In buggy contract: if overflow happened, Acc[BOB].balance could be < depositAmount, and collectAmount up to depositAmount may succeed,
        // causing contract's ether balance to drop below sum of recorded balances.
        vm.assume(collectAmount <= depositAmount);

        uint256 totalRecordedBefore = c.Acc(ALICE).balance + c.Acc(BOB).balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(BOB);
        try c.Collect(collectAmount) { } catch { }

        uint256 totalRecordedAfter = c.Acc(ALICE).balance + c.Acc(BOB).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // Invariant: contract ether balance never falls below sum of recorded Acc balances.
        // In the correct contract, this always holds because balances are updated atomically and no overflow.
        // In the buggy contract, overflow in Put can cause recorded balance underflow, making this fail.
        assertTrue(contractBalanceAfter >= totalRecordedAfter);
    }
}

