pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositVal, uint256 collectVal, uint256 lockTime) public {
        // 1. Bound to admissible domain: wide, but avoid unreasonable values that break tests
        depositVal = bound(depositVal, 1, type(uint128).max);
        collectVal = bound(collectVal, 1, type(uint128).max);
        lockTime = bound(lockTime, 1, type(uint64).max);

        // 2. Setup: initialize contract, set min sum to 0 so Collect can proceed
        address alice = address(0xA11CE);
        vm.deal(alice, depositVal);
        c.SetMinSum(0);
        c.Initialized();

        // Alice deposits via Put (overflows in buggy version)
        vm.prank(alice);
        c.Put{value: depositVal}(lockTime);

        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // Alice collects (collectVal <= depositVal after overflow? We'll see)
        vm.prank(alice);
        try c.Collect(collectVal) {} catch {}

        // 3. Assertion: Contract ether balance must be >= sum of Acc balances of Alice
        ( , uint256 aliceBalance) = c.Acc(alice);
        uint256 contractBal = address(c).balance;
        assertTrue(contractBal >= aliceBalance, "Contract balance less than recorded balance");
    }
}

