pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 lockTime, uint256 collectAmt) public {
        // bound amounts to avoid immediate reverts from zero or excessive collect
        vm.assume(amount > 0);
        vm.assume(collectAmt > 0);
        vm.assume(lockTime <= type(uint64).max);

        // initialize the contract
        c.Initialized();
        c.SetMinSum(1);

        // fund two distinct EOAs to get two accounts into c
        address alice = address(0x100);
        address bob = address(0x200);
        vm.deal(alice, amount);
        vm.deal(bob, amount);

        vm.prank(alice);
        c.Put{value: amount}(lockTime);
        vm.prank(bob);
        c.Put{value: amount}(lockTime);

        // warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // try a Collect on behalf of alice, using collectAmt that is ≤ her recorded balance
        vm.assume(collectAmt <= amount);

        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(alice);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint256 balanceAfter = address(c).balance;
            // After a successful Collect, the remaining ether must be at least MinSum for every remaining account that has a non-zero balance.
            // Both accounts initially deposited 'amount'. After alice collects 'collectAmt', alice's recorded balance is amount - collectAmt,
            // bob's balance is still amount. The contract ether balance should be at least MinSum * 2 if both balances are non-zero.
            // The bug causes alice's recorded balance to be far smaller due to overflow during Put, so this invariant can be violated.
            uint256 aliceBal = c.Acc(alice).balance;
            uint256 bobBal = c.Acc(bob).balance;
            uint256 minExpected = 0;
            if (aliceBal > 0) minExpected += c.MinSum();
            if (bobBal > 0) minExpected += c.MinSum();
            assertTrue(balanceAfter >= minExpected);
        } else {
            // revert is ok for reference; in buggy version a revert may also happen but the property is about successful Collect only
        }
    }
}

