pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint16 lockTime) public {
        // 1. keep domain wide: depositAmount > 0 to trigger overflow scenario, collectAmount less than or equal to depositAmount (but not zero)
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        // 2. setup: initialize contract
        vm.startPrank(address(this));
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        vm.stopPrank();
        // fund an actor and deposit
        address alice = makeAddr("alice");
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        c.Put{value: depositAmount}(lockTime);
        // record balance before collect
        uint256 balanceBefore = c.Acc(alice).balance;
        // warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);
        // collect
        vm.prank(alice);
        bool ok = false;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        // 3. assert: if collect succeeded, recorded balance decreased by exactly collectAmount
        if (ok) {
            uint256 balanceAfter = c.Acc(alice).balance;
            assert(balanceAfter == balanceBefore - collectAmount);
        } else {
            assert(true); // no revert, property vacuously holds
        }
    }
}

